package tools.aqua.dse.preprocessing;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Parsed form of a constructor signature as generated by
 * {@link Opal#generateSignaturesOfPossibleConstructorCallsFromNondetObject(int)}.
 *
 * <p>Format: {@code Class|Descriptor|{P1}{P2}...{Pn}}, where {@code {}} is a primitive parameter and
 * {@code {...}} a nested constructor signature for a reference parameter. {@code null|NULL} denotes
 * the null value. Examples:
 * <pre>{@code
 * null|NULL
 * LB;|()V|
 * LB;|(I)V|{}
 * LC;|(LA;)V|{LB;|(I)V|{}}
 * }</pre>
 *
 * @param signature  the raw signature string (without the {@code <>} error marker used during summarization).
 * @param rootClass  JVM type name of the constructed class, or {@code "null"} for {@code null|NULL}.
 * @param descriptor JVM descriptor of the root constructor, or {@code "NULL"}.
 * @param arguments  the raw argument strings (content of the {@code {}} groups; empty string for primitives).
 * @param depth      nesting depth: 0 for {@code null|NULL}, 1 for constructors without nested constructor
 *                   calls, 1 + max depth of nested constructors otherwise.
 */
public record ConstructorSignature(String signature,
                                   String rootClass,
                                   String descriptor,
                                   List<String> arguments,
                                   int depth) {

    public static final String NULL_SIGNATURE = "null|NULL";

    /**
     * Orders signatures by depth, then number of parameters, then lexicographically (deterministic).
     */
    public static final Comparator<ConstructorSignature> SIMPLEST_FIRST =
            Comparator.comparingInt(ConstructorSignature::depth)
                    .thenComparingInt(s -> s.arguments().size())
                    .thenComparing(ConstructorSignature::signature);

    public boolean isNull() {
        return NULL_SIGNATURE.equals(signature);
    }

    /**
     * @return all nested constructor signatures (transitively), excluding {@code null|NULL} and primitives.
     */
    public List<ConstructorSignature> nestedConstructors() {
        List<ConstructorSignature> result = new ArrayList<>();
        for (String arg : arguments) {
            if (isConstructorArgument(arg)) {
                ConstructorSignature nested = parse(arg);
                result.add(nested);
                result.addAll(nested.nestedConstructors());
            }
        }
        return result;
    }

    public static ConstructorSignature parse(String signature) {
        if (signature.startsWith("<")) {
            throw new IllegalArgumentException("Signature carries an error marker: " + signature);
        }
        if (NULL_SIGNATURE.equals(signature)) {
            return new ConstructorSignature(signature, "null", "NULL", List.of(), 0);
        }
        int first = signature.indexOf('|');
        int second = first < 0 ? -1 : signature.indexOf('|', first + 1);
        if (first < 0 || second < 0) {
            throw new IllegalArgumentException("Malformed constructor signature: " + signature);
        }
        String rootClass = signature.substring(0, first);
        String descriptor = signature.substring(first + 1, second);
        List<String> arguments = splitArguments(signature.substring(second + 1), signature);

        int depth = 1;
        for (String arg : arguments) {
            if (isConstructorArgument(arg)) {
                depth = Math.max(depth, 1 + parse(arg).depth());
            }
        }
        return new ConstructorSignature(signature, rootClass, descriptor, List.copyOf(arguments), depth);
    }

    private static boolean isConstructorArgument(String arg) {
        return !arg.isEmpty() && !NULL_SIGNATURE.equals(arg);
    }

    private static List<String> splitArguments(String args, String signature) {
        List<String> result = new ArrayList<>();
        int level = 0;
        int start = -1;
        for (int i = 0; i < args.length(); i++) {
            char c = args.charAt(i);
            if (c == '{') {
                if (level == 0) {
                    start = i + 1;
                }
                level++;
            } else if (c == '}') {
                level--;
                if (level == 0) {
                    result.add(args.substring(start, i));
                } else if (level < 0) {
                    throw new IllegalArgumentException("Unbalanced braces in signature: " + signature);
                }
            } else if (level == 0) {
                throw new IllegalArgumentException("Unexpected character '" + c + "' in signature: " + signature);
            }
        }
        if (level != 0) {
            throw new IllegalArgumentException("Unbalanced braces in signature: " + signature);
        }
        return result;
    }
}
